const A = (bible, extra = {}) => ({ src: 'kjva', bible, ...extra });

const subjects = {
  'creation': { title: 'The Creation', kind: 'bible', about: 'The Book of Genesis opens with God making the world in six days: light first, then the sky and the waters, the land and its plants, the sun, moon and stars, the creatures of sea and air and land, and last of all man and woman. On the seventh day He rested. Michelangelo painted the story along the spine of the Sistine Chapel ceiling between 1508 and 1512, beginning at the altar end with God dividing light from darkness.' },
  'adam-and-eve': { title: 'Adam and Eve', kind: 'bible', about: 'God shaped Adam from the dust and breathed life into him, then made Eve from his rib while he slept, and set them in the Garden of Eden. They could eat of every tree but one, the tree of the knowledge of good and evil. Tempted by the serpent, Eve ate its fruit and gave it to Adam; their eyes were opened, they knew they were naked, and God drove them out of the garden to work the ground.' },
  'noah': { title: 'Noah and the Flood', kind: 'bible', about: 'Seeing the wickedness of the world, God resolved to destroy it by water, but told Noah, the one righteous man, to build an ark and take his family and a pair of every living creature into it. It rained forty days and nights and the waters covered the mountains. When they went down Noah sent out a raven and then a dove; when the dove came back with an olive leaf he knew the earth was dry. Noah gave thanks with a sacrifice, planted a vineyard, and once lay drunk and uncovered in his tent, where his sons found him.' },
  'abraham': { title: 'Abraham', kind: 'bible', about: 'Abraham, the father of the people of Israel, left his homeland at God\'s call and was promised descendants as many as the stars. After he rescued his nephew Lot from four kings, Melchizedek, king of Salem and priest of God, came out to meet him with bread and wine and blessed him. Years later God tested Abraham by asking him to sacrifice Isaac, the son of his old age; an angel stopped his hand and a ram caught in a thicket was offered instead.' },
  'joseph': { title: 'Joseph and his Brothers', kind: 'bible', about: 'Jacob loved his son Joseph more than his other sons and gave him a coat of many colours, and the brothers hated him for it and for his dreams of ruling over them. They sold him to traders bound for Egypt, dipped the coat in a goat\'s blood and brought it to their father, who believed a wild beast had killed him. Joseph rose to govern Egypt and in time forgave them.' },
  'moses': { title: 'Moses', kind: 'bible', about: 'Moses, born a Hebrew in Egypt and raised in Pharaoh\'s household, killed an Egyptian he saw beating a Hebrew slave and fled to Midian, where he defended the daughters of Jethro at a well and married one of them. God spoke to him from a bush that burned without being consumed and sent him back to lead his people out of Egypt. In the wilderness Korah and his followers rose against Moses and Aaron, and the earth opened and swallowed them.' },
  'scapegoat': { title: 'The Scapegoat', kind: 'bible', about: 'On the Day of Atonement, the law of Leviticus told the high priest to lay his hands on the head of a goat, confess over it the sins of the people, and send it away into the wilderness to carry them off. Christians read it as a figure of Christ, who bore the sins of others.' },
  'david': { title: 'David', kind: 'bible', about: 'David, the youngest son of Jesse, was a shepherd boy from Bethlehem who became Israel\'s greatest king. He killed the Philistine giant Goliath with a stone from his sling and cut off his head with the giant\'s own sword. King Saul\'s son Jonathan loved him as his own soul, and warned him of his father\'s jealousy with a sign of arrows shot in a field. As an outlaw David was turned from vengeance against the churl Nabal by Nabal\'s wise wife Abigail, whom he later married. He is also the traditional author of the Psalms.' },
  'elijah': { title: 'Elijah', kind: 'bible', about: 'Elijah was a prophet of Israel in the reign of King Ahab. During a famine a widow of Zarephath shared her last meal with him, and when her son fell sick and died Elijah carried him to an upper room, stretched himself on the child three times and prayed, and the boy lived. Later, fleeing Queen Jezebel, he lay down under a juniper tree in the wilderness and asked to die, and an angel woke him and gave him bread and water.' },
  'esther': { title: 'Esther', kind: 'bible', about: 'Esther, a Jewish orphan raised by her cousin Mordecai, became queen to the Persian king Ahasuerus without revealing her people. When the minister Haman won a decree to destroy the Jews, Esther went before the king unbidden, though anyone who did so could be put to death unless he held out his golden sceptre. The Greek additions to the book, in the Apocrypha, tell how she fainted at his fierce look and how he leapt from his throne to hold her.' },
  'daniel': { title: 'Daniel in the Lions\' Den', kind: 'bible', about: 'Daniel, a young Jewish exile at the Persian court, kept praying to God after King Darius had forbidden prayer to anyone but himself. He was thrown into a den of lions and the mouth of the den sealed with a stone. In the morning the king found him unhurt: God had sent an angel to shut the lions\' mouths.' },
  'prophets': { title: 'The Prophets', kind: 'bible', about: 'The prophets of the Old Testament spoke for God to Israel, warning, consoling and foretelling. Christians read many of their words as pointing to Christ, which is why seven of them sit around the Sistine Chapel ceiling, alternating with five sibyls, the prophetesses of the pagan world.' },
  'sibyls': { title: 'The Sibyls', kind: 'legend', about: 'The sibyls were the prophetesses of the ancient Greek and Roman world, each tied to a shrine: Delphi, Erythrae, Cumae, Libya, Persia. Medieval Christians believed they too had foretold the coming of Christ, and so Michelangelo set five of them on the Sistine Chapel ceiling beside seven Hebrew prophets, each with a book or scroll of her oracles.' },
  'tree-of-jesse': { title: 'The Tree of Jesse', kind: 'bible', about: 'Isaiah foretold that a shoot would spring from the stem of Jesse, father of King David. Medieval artists drew it as a tree growing from the sleeping Jesse, with the kings of Israel in its branches and the Virgin and Christ at its top, to show Christ\'s descent from David.' },
  'judith': { title: 'Judith and Holofernes', kind: 'apocrypha', about: 'The Book of Judith, in the Apocrypha, tells of a widow of the besieged town of Bethulia. When the Assyrian general Holofernes had cut off its water, Judith dressed in her finest clothes, went with her maid to his camp and won his trust. On the fourth night, when he lay drunk in his tent, she took down his sword, cut off his head, and carried it home in a bag of food. The Assyrians found his headless body in the morning and fled.' },
  'susanna': { title: 'Susanna and the Elders', kind: 'apocrypha', about: 'The History of Susanna, in the Apocrypha, tells of a virtuous wife in Babylon. Two elders who lusted after her hid in her garden while she bathed and threatened to swear she had lain with a young man unless she gave in to them. She refused, was condemned to death on their word, and was saved when the young Daniel questioned the two apart and caught them in their lie.' },
  'annunciation': { title: 'The Annunciation', kind: 'bible', about: 'In the Gospel of Luke the angel Gabriel is sent to Nazareth, to a young woman named Mary who was promised in marriage to Joseph, and tells her that she will bear a son and call him Jesus. Mary is troubled, asks how this can be, and accepts: "Behold the handmaid of the Lord." Painters show the angel kneeling with a lily, the flower of purity, and Mary often at her reading.' },
  'madonna': { title: 'The Virgin and Child', kind: 'bible', about: 'The Virgin Mary holding the infant Jesus was the most painted subject of the Renaissance, made for altars, chapels and the private prayer of a household. The Gospels say little of the Child\'s infancy, so painters filled their pictures with signs: a pomegranate for the Resurrection, a goldfinch or a carnation for the Passion to come, a book for the prophecies, and the young John the Baptist, Christ\'s cousin, as the herald who would point him out.' },
  'magnificat': { title: 'The Magnificat', kind: 'bible', about: 'When Mary visited her cousin Elizabeth after the Annunciation, she answered Elizabeth\'s greeting with a song of praise that begins, in Latin, "Magnificat anima mea Dominum": "My soul doth magnify the Lord." It has been sung at evening prayer ever since.' },
  'nativity': { title: 'The Nativity', kind: 'bible', about: 'Luke tells how Joseph and Mary travelled to Bethlehem for a census, found no room at the inn, and laid the newborn Jesus in a manger. An angel announced the birth to shepherds keeping watch over their flocks, a host of angels sang "Glory to God in the highest", and the shepherds went to Bethlehem to see the child.' },
  'magi': { title: 'The Adoration of the Magi', kind: 'bible', about: 'Matthew tells of wise men from the east who followed a star to Bethlehem, asking where the King of the Jews was born. They found the child with Mary his mother, worshipped him, and gave him gold, frankincense and myrrh. Later tradition made them three kings, named them Caspar, Melchior and Balthasar, and gave them the three ages of man and, in time, the three known continents. Florentine painters liked to put the Medici and their friends in the crowd.' },
  'circumcision': { title: 'The Circumcision of Christ', kind: 'bible', about: 'Following Jewish law, Jesus was circumcised on the eighth day after his birth and given the name the angel had told Mary. The church kept the feast on the first of January, and painters showed it as a ceremony in the Temple.' },
  'flight-into-egypt': { title: 'The Flight into Egypt', kind: 'bible', about: 'After the wise men left, an angel warned Joseph in a dream that King Herod meant to kill the child, and the Holy Family fled by night into Egypt. Herod, finding himself deceived, ordered every boy of two years and under in Bethlehem to be killed, the Massacre of the Innocents. Legends of the journey told of palm trees bending to give the family dates and of rests along the road.' },
  'finding-in-temple': { title: 'The Finding of Christ in the Temple', kind: 'bible', about: 'When Jesus was twelve his parents took him to Jerusalem for Passover and started home without him. After three days of searching they found him in the Temple, sitting among the teachers, listening and asking questions, and all who heard him were astonished. To his mother\'s reproach he answered: "Wist ye not that I must be about my Father\'s business?"' },
  'holy-family': { title: 'The Holy Family', kind: 'bible', about: 'The Holy Family is the Child with Mary and Joseph, often joined by Mary\'s mother, Saint Anne, and the infant John the Baptist with his mother Elizabeth. The Gospels give almost nothing of the years between the infancy and the ministry, so painters imagined quiet family scenes, often with signs of the Passion to come.' },
  'saint-anne': { title: 'Saint Anne', kind: 'legend', about: 'Saint Anne, the mother of the Virgin Mary, is not named in the Bible; her story comes from the second-century Protevangelium of James, which tells how she and Joachim were childless until an angel promised them a daughter. She was much venerated in the late Middle Ages, and painters showed her with Mary and the Child as three generations together.' },
  'john-the-baptist': { title: 'John the Baptist', kind: 'bible', about: 'John, the cousin of Jesus, was the last of the prophets. He lived in the wilderness of Judaea, dressed in camel\'s hair with a leather girdle and eating locusts and wild honey, and preached repentance, baptizing in the river Jordan. When he saw Jesus coming he said, "Behold the Lamb of God." Painters show him with a reed cross and a lamb or ram. He was imprisoned by Herod Antipas for condemning his marriage to Herodias, and beheaded at the request of her daughter Salome.' },
  'baptism': { title: 'The Baptism of Christ', kind: 'bible', about: 'Jesus came from Galilee to the Jordan to be baptized by John. As he came up out of the water, the heavens opened, the Spirit of God came down like a dove, and a voice from heaven said, "This is my beloved Son, in whom I am well pleased."' },
  'temptation': { title: 'The Temptations of Christ', kind: 'bible', about: 'After his baptism Jesus fasted forty days in the wilderness, and the devil came to tempt him three times: to turn stones into bread, to throw himself from the pinnacle of the Temple, and to take all the kingdoms of the world in return for worshipping him. Each time Jesus answered with scripture, and the devil left him.' },
  'calling-of-apostles': { title: 'The Calling of the Apostles', kind: 'bible', about: 'Jesus chose his first followers from ordinary working men. Walking by the Sea of Galilee he saw the fishermen Simon Peter and his brother Andrew casting a net and said, "Follow me, and I will make you fishers of men." Later he saw Matthew, a tax collector, sitting at the receipt of custom, and called him too.' },
  'cleansing-temple': { title: 'Christ Cleansing the Temple', kind: 'bible', about: 'Coming to Jerusalem for Passover, Jesus found the Temple courts full of men selling cattle, sheep and doves and changing money. He made a whip of cords, drove them all out and overturned the tables, saying they had made his Father\'s house a house of merchandise.' },
  'martha-and-mary': { title: 'Martha and Mary', kind: 'bible', about: 'Luke tells how Jesus visited the house of two sisters: Martha busied herself serving, while Mary sat at his feet and listened. Martha complained, and Jesus answered that Mary had chosen the better part. Tradition made this Mary one with Mary Magdalene, and painters showed Martha persuading her worldly sister to turn from vanity.' },
  'mary-magdalene': { title: 'Mary Magdalene', kind: 'bible', about: 'Mary Magdalene followed Jesus, stood at the foot of the cross, and was the first to see him risen. Western tradition merged her with the sinful woman who washed Jesus\'s feet with her tears and dried them with her hair, and with Mary of Bethany, making her the great example of the repentant sinner. The Golden Legend tells that she ended her life as a hermit in Provence, lifted up each day by angels.' },
  'lazarus': { title: 'The Raising of Lazarus', kind: 'bible', about: 'Lazarus of Bethany, the brother of Martha and Mary, fell sick and died, and had lain in the tomb four days when Jesus came. Jesus wept, had the stone taken away, and cried with a loud voice, "Lazarus, come forth," and the dead man came out, bound hand and foot in grave clothes.' },
  'salome': { title: 'The Beheading of John the Baptist', kind: 'bible', about: 'Herod Antipas had imprisoned John for condemning his marriage to Herodias, his brother\'s wife. At Herod\'s birthday feast Herodias\'s daughter, whom tradition names Salome, danced and pleased him so much that he swore to give her whatever she asked. Prompted by her mother, she asked for John\'s head on a charger, and Herod, unwilling to break his oath before his guests, sent an executioner to the prison.' },
  'last-supper': { title: 'The Last Supper', kind: 'bible', about: 'On the night before he died, Jesus ate the Passover meal with his twelve apostles. During supper he said, "One of you shall betray me," and each of them asked in turn, "Lord, is it I?" He then blessed and broke bread and gave them wine, saying "This is my body" and "This is my blood". Judas had already agreed to hand him over for thirty pieces of silver.' },
  'passion': { title: 'The Passion of Christ', kind: 'bible', about: 'The Passion is the suffering of Jesus from his arrest to his death. Judas led armed men to the garden of Gethsemane and singled him out with a kiss. That night Peter, warned he would deny his master three times before the cock crowed, did so. Pontius Pilate had Jesus scourged; the soldiers crowned him with thorns and mocked him; Pilate showed him to the crowd saying "Behold the man!" and gave him up to be crucified.' },
  'crucifixion': { title: 'The Crucifixion', kind: 'bible', about: 'Jesus was crucified outside Jerusalem between two thieves. From the sixth hour to the ninth there was darkness over the land; then he cried with a loud voice, commended his spirit to his Father, and died. His mother, Mary Magdalene and the apostle John stood by the cross.' },
  'entombment': { title: 'The Lamentation and Entombment', kind: 'bible', about: 'After the Crucifixion, Joseph of Arimathea, a secret follower, asked Pilate for the body, and with Nicodemus took it down from the cross, wound it in linen with myrrh and aloes, and laid it in a new tomb cut in the rock. Painters showed the mourning over the body, the Lamentation, and its carrying to the tomb, the Entombment.' },
  'emmaus': { title: 'The Supper at Emmaus', kind: 'bible', about: 'On the day of the Resurrection two disciples walking to the village of Emmaus were joined by a stranger who explained the scriptures to them. They asked him to stay and eat, and when he blessed and broke the bread their eyes were opened and they knew him as the risen Jesus, and he vanished from their sight.' },
  'doubting-thomas': { title: 'The Incredulity of Saint Thomas', kind: 'bible', about: 'The apostle Thomas was not with the others when the risen Jesus first appeared to them, and said he would not believe unless he put his finger into the print of the nails and his hand into the wound in his side. Eight days later Jesus appeared again and told him to do so, and Thomas answered, "My Lord and my God."' },
  'conversion-of-paul': { title: 'The Conversion of Saint Paul', kind: 'bible', about: 'Saul of Tarsus was a zealous persecutor of the first Christians. On the road to Damascus a light from heaven struck him to the ground and a voice said, "Saul, Saul, why persecutest thou me?" Blinded, he was led into the city, where after three days a disciple restored his sight and baptized him. As Paul he became the great apostle to the Gentiles.' },
  'apostle-paul': { title: 'Saint Paul the Apostle', kind: 'bible', about: 'Paul carried the Christian faith across the Roman world and wrote the letters that make up much of the New Testament. Tradition says he was beheaded in Rome under Nero, and he is shown with the sword of his martyrdom and the book or letters of his teaching.' },
  'john-evangelist': { title: 'Saint John the Evangelist', kind: 'bible', about: 'John, the youngest of the apostles and "the disciple whom Jesus loved", was by tradition the author of the fourth Gospel and of the Book of Revelation, which he wrote in exile on the island of Patmos after visions of the end of the world. His sign is the eagle, the creature of the highest vision.' },
  'revelation': { title: 'The Book of Revelation', kind: 'bible', about: 'The last book of the Bible records the visions of John on Patmos: letters to seven churches, the throne of God, the seven seals, the woman clothed with the sun, the last judgement when the sea gives up its dead, and the new Jerusalem. Its images have fed painters for centuries.' },
  'works-of-mercy': { title: 'The Seven Works of Mercy', kind: 'bible', about: 'In the Gospel of Matthew, Jesus describes the last judgement: the blessed are those who fed the hungry, gave drink to the thirsty, welcomed the stranger, clothed the naked, visited the sick and those in prison, for "inasmuch as ye have done it unto one of the least of these my brethren, ye have done it unto me." The church added burying the dead to make seven.' },
  'death-of-the-virgin': { title: 'The Death of the Virgin', kind: 'legend', about: 'The Bible says nothing of Mary\'s death. Legends gathered in the Golden Legend tell that an angel warned her three days before, that the apostles were carried miraculously from wherever they were preaching to be at her bedside, and that Christ came to receive her soul. The Catholic Church holds that she was then taken up body and soul into heaven, the Assumption.' },
  'awakening-conscience': { title: 'The Awakening Conscience', kind: 'scripture-quoted', about: 'Holman Hunt\'s picture is not from the Bible, but he framed it in scripture. A kept woman, sitting at the piano in the room her lover has taken for her, rises from his lap as the song they are singing, Thomas Moore\'s "Oft in the Stilly Night", recalls her childhood, and she sees through the window the garden and the light outside. On the frame Hunt carved a verse from Proverbs.' },
  'hope': { title: 'Hope', kind: 'allegory', about: 'Hope is one of the three theological virtues with Faith and Charity, the "faith, hope, charity" of Saint Paul. Renaissance painters showed her as a woman reaching upward, and Burne-Jones, painting her in 1896 after the death of his friend William Morris, showed her chained and still reaching.' },
  'wings-of-the-morning': { title: 'Wings of the Morning', kind: 'scripture-quoted', about: 'The title comes from Psalm 139, in which the psalmist says there is nowhere he can go from God\'s presence: not to heaven, not to the grave, not even if he takes "the wings of the morning" to the far side of the sea. Hughes painted a winged figure of the dawn flying over the sea at first light.' },
  'work': { title: 'Work', kind: 'scripture-quoted', about: 'Ford Madox Brown spent thirteen years on this picture of navvies digging a drain in Hampstead, ringed by every class of Victorian society, from the idle rich on horseback to the ragged flower-seller. The two men standing on the right are the writers Thomas Carlyle and F. D. Maurice, the "brain-workers" who preached the dignity of labour. Brown carved four verses of scripture about work on the frame.' },
};

